const STAGES=['Novo','Qualificação','Diagnóstico','Proposta','Negociação','Fechado','Perdido'];
const STAGE_TONES={Novo:'grey',Qualificação:'blue',Diagnóstico:'purple',Proposta:'orange',Negociação:'orange',Fechado:'green',Perdido:'red'};
const REPS=[{id:'rep-01',name:'Ana Souza',initials:'AS',region:'Relacionamento e indicações'},{id:'rep-02',name:'Lucas Ferreira',initials:'LF',region:'Prospecção ativa'},{id:'rep-03',name:'Marina Costa',initials:'MC',region:'Rede de parceiros'}];
const ICON={layout:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',clipboard:'<rect x="4" y="4" width="16" height="18" rx="2"/><path d="M8 2h8v4H8zM8 12h8M8 16h6"/>',columns:'<rect x="3" y="4" width="7" height="16" rx="1"/><rect x="14" y="4" width="7" height="16" rx="1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',network:'<rect x="2" y="3" width="8" height="7" rx="1"/><rect x="14" y="3" width="8" height="7" rx="1"/><rect x="8" y="15" width="8" height="7" rx="1"/><path d="M6 10v2h12v-2m-6 2v3"/>',presentation:'<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M12 17v4m-5 0h10m-9-11h8"/>',search:'<circle cx="10.8" cy="10.8" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',check:'<path d="M5 12l4 4L19 6"/>',chart:'<path d="M3 3v18h18M7 16l5-5 4 3 5-8"/>',building:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 7h2m4 0h2M8 11h2m4 0h2M9 21v-5h6v5"/>',filter:'<path d="M4 5h16M7 12h10m-7 7h4"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3"/>',file:'<path d="M7 2h7l5 5v15H5V2zM14 2v5h5M8 12h8M8 16h8"/>',alert:'<path d="M12 3 2 21h20L12 3zM12 10v4m0 4h.01"/>',circle:'<circle cx="12" cy="12" r="9"/>'};
function ic(n,size=17){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICON[n]||ICON.circle}</svg>`}
const Q=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const asDate=s=>s?new Date(s.includes('T')?s:s+'T12:00:00'):null;
const dateISO=(offset=0)=>{const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const isoTime=(offset=0)=>{const d=new Date();d.setDate(d.getDate()+offset);return d.toISOString()};
const dateFmt=(date)=>{if(!date)return 'Não agendado';const d=asDate(date);return Number.isNaN(d?.getTime())?'Não agendado':d.toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'})};
const dateShort=(date)=>{const d=asDate(date);return d?{day:String(d.getDate()).padStart(2,'0'),month:d.toLocaleDateString('pt-BR',{month:'short'}).replace('.','').toUpperCase()}:null};
const money=n=>n===null||n===undefined||n===''?'Não definido':Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0});
const nice=(v,fallback='Não informado')=>v&&String(v).trim()?esc(v):fallback;
const repName=id=>REPS.find(r=>r.id===id)?.name||'Não atribuído';
const symptomName=id=>SYMPTOMS.find(s=>s.id===id)?.name||id;
const idNew=()=>('kd-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8));
function makeOpp(id,company,sector,contact,rep,stage,symptoms,priority,description,solutions,daysAgo,nextOffset,extras={}){
 const when=isoTime(-daysAgo);return {id,company,sector,contact,rep,stage,source:'Apresentação adaptativa',symptoms,priority,description,solutions,frequency:extras.frequency||'Sem levantamento',consequence:extras.consequence||'A confirmar',impact:extras.impact||'Sem linha de base verificada; começar a medir.',objective:extras.objective||'',currentFlow:extras.currentFlow||'',systems:extras.systems||'',baseline:extras.baseline||'',successMetric:extras.successMetric||'',approver:extras.approver||'',constraints:extras.constraints||'',diagnosisStatus:extras.diagnosisStatus||'A aprofundar',value:extras.value||'',nextDate:nextOffset===null?'':dateISO(nextOffset),createdAt:when,updatedAt:when,events:[{id:idNew(),at:when,kind:'lead',title:'Oportunidade registrada',detail:'Pré-diagnóstico capturado após conversa com representante.',by:repName(rep)}],...extras};
}
function seed(){return {version:1,opps:[
makeOpp('KD-1001','Bistrô Horizonte','Restaurantes e delivery','Pessoa Gestora 01','rep-01','Diagnóstico',['service','systems','manual'],'service','Pedidos de dois canais precisam ser redigitados; a equipe recebe mensagens repetidas sobre horários e entregas.',['Agente de IA com contexto','Integração entre sistemas','Dashboard gerencial'],9,1,{frequency:'Diariamente',consequence:'Retrabalho e demora no atendimento',impact:'Cenário fictício: 19 h/mês de esforço repetitivo. Ainda não representa economia comprovada.',objective:'Reduzir redigitação e melhorar tempo de resposta.',currentFlow:'WhatsApp → planilha → cozinha → confirmação manual',systems:'WhatsApp e ferramenta de pedidos',baseline:'Ainda não medida',successMetric:'Tempo médio de resposta e pedidos sem redigitação',approver:'Gerência operacional',diagnosisStatus:'Em revisão'}),
makeOpp('KD-1002','Ponto Norte Varejo','Comércio e varejo','Pessoa Gestora 02','rep-02','Qualificação',['followup','visibility'],'followup','Orçamentos chegam por mensagens, mas o time não acompanha os retornos e não possui indicadores confiáveis.',['Automação de processos','Dashboard gerencial'],6,2,{frequency:'Semanal',consequence:'Oportunidades sem acompanhamento',impact:'Valor comercial em risco ainda não quantificado.'}),
makeOpp('KD-1003','Oficina Linha Clara','Serviços','Pessoa Gestora 03','rep-03','Proposta',['manual','orders'],'manual','Equipe perde tempo consolidando ordens de serviço e repassando o status manualmente.',['Automação de processos','Sistema ou aplicativo'],22,4,{frequency:'Diariamente',consequence:'Horas administrativas',impact:'Cenário fictício de capacidade consumida, ainda sem validação.',objective:'Centralizar a entrada e execução das ordens.',systems:'Planilhas e mensagens',baseline:'Estimativa inicial de 7 h/semana',successMetric:'Tempo de atualização por ordem',diagnosisStatus:'Validado para escopo',value:12000}),
makeOpp('KD-1004','Terracota Engenharia','Engenharia e obras','Pessoa Gestora 04','rep-01','Negociação',['visibility','orders','systems'],'visibility','Etapas da obra e compras são informadas por mensagens e planilhas, atrasando a visão dos responsáveis.',['Dashboard gerencial','Integração entre sistemas'],19,0,{frequency:'Semanal',consequence:'Atraso nas decisões',impact:'Impacto qualitativo identificado; valor financeiro não medido.',objective:'Acompanhar cronograma e pendências em um único painel.',currentFlow:'Campo → planilha → reunião → decisão',systems:'Planilhas e sistema de compras',baseline:'Relatório manual semanal',successMetric:'Atualização dentro do prazo acordado',approver:'Direção de operações',diagnosisStatus:'Validado para escopo',value:24500}),
makeOpp('KD-1005','LogWay Operações','Logística e entregas','Pessoa Gestora 05','rep-02','Novo',['orders','service'],'orders','Equipe recebe solicitações de status e procura informações de entregas em vários lugares.',['Integração entre sistemas','Agente de IA com contexto'],2,3,{frequency:'Diariamente'}),
makeOpp('KD-1006','Clínica Caminho','Saúde e clínicas','Pessoa Gestora 06','rep-03','Diagnóstico',['service','manual'],'service','Recepção responde perguntas repetitivas sobre horários; dados pessoais exigem regras de privacidade.',['Agente de IA com contexto','Automação de processos'],15,-2,{frequency:'Diariamente',consequence:'Tempo da recepção',objective:'Melhorar triagem sem expor informações sensíveis.',currentFlow:'Mensagem → recepção → confirmação',systems:'Agenda e WhatsApp',constraints:'Exigir análise de privacidade antes de qualquer integração.',diagnosisStatus:'Aguardando dados'}),
makeOpp('KD-1007','Estúdio Central','Serviços','Pessoa Gestora 07','rep-01','Fechado',['systems','manual'],'systems','Informações de vendas e execução estavam dispersas.',['Integração entre sistemas','Automação de processos'],39,null,{frequency:'Semanal',consequence:'Retrabalho',objective:'Reduzir duplicidade de registros.',currentFlow:'CRM → planilha → equipe',systems:'CRM e planilhas',baseline:'12 ocorrências por semana (exemplo)',successMetric:'Ocorrências de retrabalho',approver:'Direção',diagnosisStatus:'Validado para escopo',value:18500}),
makeOpp('KD-1008','Produto Aurora','Tecnologia e SaaS','Pessoa Gestora 08','rep-02','Proposta',['newproduct','growth'],'newproduct','Precisa validar uma plataforma para clientes antes de investir em toda a arquitetura.',['MVP e produto digital','Sistema ou aplicativo'],25,5,{frequency:'Oportunidade estratégica',consequence:'Risco de investir sem validar',objective:'Validar jornada principal com usuários reais.',systems:'Protótipo inicial',successMetric:'Conclusão da tarefa-chave por usuários de teste',diagnosisStatus:'Validado para escopo',value:32000}),
makeOpp('KD-1009','Indústria Atlas','Indústria','Pessoa Gestora 09','rep-03','Perdido',['mistakes','manual'],'mistakes','Conferência manual gera inconsistências em registros de produção.',['Automação de processos','Dashboard gerencial'],52,null,{frequency:'Diariamente',consequence:'Retrabalho',diagnosisStatus:'A aprofundar'}),
makeOpp('KD-1010','Bistrô Horizonte','Restaurantes e delivery','Pessoa Gestora 01','rep-01','Qualificação',['growth','visibility'],'growth','Além do atendimento, a empresa deseja um painel de gestão de entregadores para uma etapa futura.',['Dashboard gerencial','Sistema ou aplicativo'],3,9,{frequency:'Semanal',consequence:'Falta de acompanhamento',impact:'Não quantificado.'})
]};}
let data=load();let state={view:'dashboard',role:'manager',search:'',filterStage:'all',filterSector:'all',diagFilter:'all',activeOpp:null,tab:'overview',notice:true};
function load(){try{const raw=localStorage.getItem(STORE_KEY);if(raw){const v=JSON.parse(raw);if(v&&Array.isArray(v.opps)&&v.version===1)return v}}catch(e){}return seed()}
function persist(){try{localStorage.setItem(STORE_KEY,JSON.stringify(data));return true}catch(e){toast('Não foi possível gravar neste navegador. As mudanças podem não persistir.');return false}}
function toast(msg){const el=Q('toast');el.textContent=msg;el.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>el.hidden=true,3000)}
function visible(){return data.opps.filter(o=>state.role==='manager'||o.rep===state.role)}
function get(id){return data.opps.find(o=>o.id===id)}
function countFields(o){const fields=[Boolean(o.priority),Boolean(o.description?.trim()),Boolean(o.objective?.trim()),Boolean(o.currentFlow?.trim()),Boolean(o.systems?.trim()),Boolean(o.successMetric?.trim())];return {score:fields.filter(Boolean).length,total:fields.length,done:Math.round(100*fields.filter(Boolean).length/fields.length),fields}}
function stagePill(stage){return `<span class="pill" data-tone="${STAGE_TONES[stage]||'grey'}">${esc(stage)}</span>`}
function diagnosisPill(status){return `<span class="pill" data-tone="${status==='Validado para escopo'?'green':status==='Em revisão'?'blue':status==='Aguardando dados'?'orange':'grey'}">${esc(status)}</span>`}
function event(o,title,detail,kind='note'){o.events.unshift({id:idNew(),at:new Date().toISOString(),title,detail,kind,by:state.role==='manager'?'Equipe Kadelta':repName(state.role)})}
function saveOpp(o,label,detail){o.updatedAt=new Date().toISOString();event(o,label,detail);persist();render();if(state.activeOpp===o.id)renderDrawer();toast('Alteração salva nesta demonstração.')}
function viewTitle(){return {dashboard:'Visão geral',leads:'Carteira de leads',diagnostics:'Diagnósticos',pipeline:'Negociações',agenda:'Agenda e retornos',network:'Representantes'}[state.view]||'Visão geral'}
function setView(v){state.view=v;Q('breadcrumbView').textContent=viewTitle();for(const el of document.querySelectorAll('[data-view]'))el.classList.toggle('active',el.dataset.view===v);Q('sidebar').classList.remove('open');Q('mobileScrim').hidden=true;render();window.scrollTo({top:0,behavior:'instant'});}
const heading=(kicker,title,desc,actions='')=>`<header class="page-heading"><div><div class="eyebrow">${kicker}</div><h1 class="page-title">${title}</h1><p class="page-description">${desc}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</header>`;
const actionBtn=(name,cmd,primary=false)=>`<button class="${primary?'primary-btn':'secondary-btn'}" type="button" data-action="${cmd}">${primary?'＋ ':''}${name}</button>`;
function render(){Q('navLeadCount').textContent=visible().length;const root=Q('view');root.innerHTML=state.view==='dashboard'?renderDashboard():state.view==='leads'?renderLeads():state.view==='diagnostics'?renderDiagnostics():state.view==='pipeline'?renderPipeline():state.view==='agenda'?renderAgenda():renderNetwork();}
function renderDashboard(){const arr=visible(),active=arr.filter(o=>!['Fechado','Perdido'].includes(o.stage)),need=arr.filter(o=>!['Fechado','Perdido'].includes(o.stage)&&countFields(o).done<100),closed=arr.filter(o=>o.stage==='Fechado'),due=active.filter(o=>o.nextDate&&o.nextDate<=dateISO(0)).sort((a,b)=>a.nextDate.localeCompare(b.nextDate)),soc=[...new Set(arr.map(x=>x.company))].length;
const stats=[{name:'Empresas na carteira',num:soc,icon:'building',note:'Empresas únicas, sem duplicidades'},{name:'Oportunidades abertas',num:active.length,icon:'chart',note:'Em alguma etapa comercial'},{name:'Diagnósticos incompletos',num:need.length,icon:'clipboard',note:'Exigem perguntas ou validação'},{name:'Retornos até hoje',num:due.length,icon:'clock',note:'Inclui tarefas em atraso'}];
let symCounts=SYMPTOMS.map(s=>({label:s.name,n:arr.filter(o=>o.symptoms.includes(s.id)).length})).filter(s=>s.n).sort((a,b)=>b.n-a.n).slice(0,5);
return heading('CENTRAL DE OPORTUNIDADES','Todo problema começa com uma conversa.','Acompanhe o que foi identificado, o que precisa ser validado e o próximo movimento comercial.',actionBtn('Importar diagnóstico','import')+actionBtn('Novo lead','new',true))+
`<div class="dark-hero"><div><span class="eyebrow">A INTELIGÊNCIA COMERCIAL DA KADELTA</span><h2>Do sintoma<br>à <em>decisão certa.</em></h2><p>O representante identifica a dor. A Kadelta valida o diagnóstico. A oportunidade avança sem perder contexto ou histórico.</p><div class="hero-actions-row"><button class="primary-btn" data-action="switch" data-target="diagnostics">Ver diagnósticos ↗</button><button class="secondary-btn hero-outline" data-action="switch" data-target="pipeline">Abrir funil →</button></div></div><div class="hero-right"><div class="hero-small"><span>OPORTUNIDADES QUE PRECISAM DE ANÁLISE</span><strong>${need.length}</strong><span>Uma dor identificada não é ainda uma solução validada.</span></div></div></div>`+
`<div class="metrics">${stats.map(s=>`<div class="metric"><div class="metric-top"><span>${esc(s.name)}</span><span class="metric-icon">${ic(s.icon,16)}</span></div><div class="metric-value">${s.num}</div><div class="metric-foot">${esc(s.note)}</div></div>`).join('')}</div>`+
`<div class="two-col"><section class="surface pad"><div class="section-top"><div><h2 class="section-title">Retornos que não podem se perder</h2><p class="section-sub">Ações vencidas ou marcadas para hoje.</p></div><button class="text-link" data-action="switch" data-target="agenda">Abrir agenda →</button></div>${due.length?`<div class="small-list">${due.slice(0,4).map(o=>`<div class="list-row" data-open-id="${o.id}"><span class="avatar">${esc(o.company.slice(0,2).toUpperCase())}</span><div><span class="row-main">${esc(o.company)}</span><div class="row-meta">${esc(symptomName(o.priority))} · ${esc(repName(o.rep))} · ${dateFmt(o.nextDate)}</div></div>${stagePill(o.stage)}</div>`).join('')}</div>`:`<div class="intro-note"><strong>Nenhum retorno vencido neste perfil.</strong><br>Abra a agenda para acompanhar os próximos contatos.</div>`}</section><section class="surface pad"><div class="section-top"><div><h2 class="section-title">Sintomas mais frequentes</h2><p class="section-sub">Contagem de oportunidades da simulação.</p></div><span class="mini-status">AMOSTRA FICTÍCIA</span></div><div class="symptom-bars">${symCounts.map(x=>`<div><div class="bar-head"><span>${esc(x.label)}</span><b>${x.n}</b></div><div class="bar-track"><div class="bar-fill" style="width:${Math.round(x.n/(symCounts[0]?.n||1)*100)}%"></div></div></div>`).join('')}</div></section></div>`+
`<div class="two-col"><section class="surface pad"><div class="section-top"><div><h2 class="section-title">Fluxo comercial da Kadelta</h2><p class="section-sub">O diagnóstico evolui, mas a atribuição comercial continua registrada.</p></div></div><div class="step-rail">${['Apresentar','Capturar','Qualificar','Diagnosticar','Negociar','Entregar'].map((x,i)=>`<div class="rail-item"><b>0${i+1}</b><span>${x}</span></div>`).join('')}</div><p class="section-sub" style="margin-top:16px">${closed.length} contrato(s) fictício(s) marcado(s) como fechado(s) nesta base demonstrativa. Não representam resultados reais da Kadelta.</p></section><section class="surface pad"><div class="section-top"><div><h2 class="section-title">Comece por aqui</h2><p class="section-sub">Caminhos rápidos para testar o sistema.</p></div></div><div class="quick-buttons"><button class="quick-button" data-action="new">${ic('plus',20)}<span>Novo cadastro</span><small>Registre uma dor e um contato fictício</small></button><button class="quick-button" data-action="import">${ic('file',20)}<span>Importar resumo</span><small>Traga o TXT da apresentação</small></button><button class="quick-button" data-action="switch" data-target="leads">${ic('users',20)}<span>Buscar empresa</span><small>Encontre o histórico do contato</small></button><button class="quick-button" data-action="switch" data-target="network">${ic('network',20)}<span>Minha rede</span><small>Compare atribuições e oportunidades</small></button></div></section></div>`;
}
function filteredLeads(){let a=visible();if(state.filterStage!=='all')a=a.filter(x=>x.stage===state.filterStage);if(state.filterSector!=='all')a=a.filter(x=>x.sector===state.filterSector);if(state.search.trim()){const search=state.search.trim().toLocaleLowerCase('pt-BR');a=a.filter(x=>[x.company,x.contact,x.sector,x.id,x.description,repName(x.rep),...x.solutions,x.priority,...x.symptoms.map(symptomName)].some(v=>String(v).toLocaleLowerCase('pt-BR').includes(search)))}return a.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))}
function renderLeads(){const a=filteredLeads();return heading('BASE COMERCIAL','Carteira de leads','Uma empresa pode ter várias oportunidades. Cada projeto mantém seu histórico e seu representante.',actionBtn('Importar da apresentação','import')+actionBtn('Cadastrar','new',true))+`<div class="toolbar"><label class="searchbox">${ic('search',16)}<input id="leadSearch" type="search" placeholder="Buscar empresa, contato, sintoma ou solução" value="${esc(state.search)}"></label><select class="filter-select" id="stageFilter" aria-label="Filtrar por etapa"><option value="all">Todas as etapas</option>${STAGES.map(x=>`<option value="${x}" ${state.filterStage===x?'selected':''}>${x}</option>`).join('')}</select><select class="filter-select" id="sectorFilter" aria-label="Filtrar por setor"><option value="all">Todos os setores</option>${SECTORS.map(x=>`<option value="${esc(x)}" ${state.filterSector===x?'selected':''}>${esc(x)}</option>`).join('')}</select><button class="secondary-btn" type="button" data-action="export">${ic('download',15)} Exportar demo</button></div><section class="surface table-surface"><div class="table-scroll"><table class="data-table"><thead><tr><th>Empresa / contato</th><th>Oportunidade</th><th>Possíveis soluções</th><th>Etapa</th><th>Representante</th><th>Próximo contato</th><th></th></tr></thead><tbody>${a.map(o=>`<tr data-open-id="${esc(o.id)}"><td><div class="company-name">${esc(o.company)}</div><div class="company-extra">${esc(o.sector)} · ${esc(o.contact)}</div></td><td><b>${esc(symptomName(o.priority))}</b><div class="company-extra">${esc(o.id)}</div></td><td>${o.solutions.slice(0,2).map(x=>`<span class="solution-chip">${esc(x)}</span>`).join('')}${o.solutions.length>2?`<span class="solution-chip">+${o.solutions.length-2}</span>`:''}</td><td>${stagePill(o.stage)}</td><td>${esc(repName(o.rep))}</td><td class="subtle">${dateFmt(o.nextDate)}</td><td><button class="link-detail" data-open-id="${esc(o.id)}">Abrir ↗</button></td></tr>`).join('')}</tbody></table></div>${a.length?`<div class="table-footer"><span>${a.length} oportunidades encontradas em ${new Set(a.map(o=>o.company)).size} empresas</span><span>Dados fictícios de demonstração</span></div>`:`<div class="empty-state"><div class="empty-symbol">Δ</div><h3>Nenhuma oportunidade encontrada.</h3><p>Altere os filtros ou cadastre um novo exemplo.</p></div>`}</section>`}
function renderDiagnostics(){const a=visible().filter(o=>!['Perdido'].includes(o.stage)).sort((a,b)=>countFields(a).done-countFields(b).done);return heading('INTELIGÊNCIA DE DIAGNÓSTICO','Fila de diagnósticos','O registro inicial mostra o sintoma; o especialista aprofunda causa, dados, objetivo e viabilidade.',actionBtn('Nova oportunidade','new',true))+`<div class="intro-note" style="margin-bottom:18px"><strong>Critério de leitura:</strong> completude indica quantas informações foram preenchidas, não a qualidade nem a aprovação técnica da solução. Os seis itens são: sintoma, relato, objetivo, fluxo atual, sistemas e métrica de sucesso.</div><div class="diag-grid">${a.map(o=>{const c=countFields(o);return `<article class="surface diag-card" data-open-id="${o.id}" tabindex="0" role="button" aria-label="Abrir diagnóstico ${esc(o.company)}"><div class="diag-head"><span class="micro-label">${esc(o.id)} · ${esc(o.sector)}</span>${diagnosisPill(o.diagnosisStatus)}</div><h3 class="diag-company">${esc(o.company)}</h3><p class="diag-problem">${esc(o.description)}</p><div class="chips">${o.symptoms.slice(0,2).map(s=>`<span class="chip alt">${esc(symptomName(s))}</span>`).join('')}${o.symptoms.length>2?`<span class="chip alt">+${o.symptoms.length-2}</span>`:''}</div><div class="progress-label"><span>Informações registradas</span><b>${c.score} de ${c.total}</b></div><div class="progress-line"><span style="width:${c.done}%"></span></div><div class="diag-bottom"><span>${esc(repName(o.rep))}</span><span>Abrir ficha →</span></div></article>`}).join('')}</div>`}
function renderPipeline(){const a=visible().sort((x,y)=>y.updatedAt.localeCompare(x.updatedAt));return heading('EVOLUÇÃO DA NEGOCIAÇÃO','Funil de oportunidades','Da identificação do sintoma até o contrato. Abra um cartão para atualizar o diagnóstico e registrar eventos.',actionBtn('Adicionar oportunidade','new',true))+`<p class="drag-instruction">${state.role==='manager'?'Arraste um cartão para mudar a etapa ou abra a ficha para alterar o estágio.':'Seu perfil de representante pode acompanhar as etapas; somente a gestão altera o estágio da negociação.'} Todas as movimentações são registradas no histórico.</p><div class="pipeline-scroll"><div class="pipeline">${STAGES.map(stage=>{const items=a.filter(o=>o.stage===stage);return `<section class="pipeline-col" data-drop-stage="${esc(stage)}"><header class="pipeline-col-header"><strong>${esc(stage)}</strong><span class="pipeline-count">${items.length}</span></header>${items.length?items.map(o=>`<article class="pipe-card" draggable="${state.role==='manager'}" data-drag-id="${o.id}" data-open-id="${o.id}"><div class="pipe-top"><span class="micro-label">${esc(o.id)}</span>${ic('arrow',14)}</div><strong class="company-name">${esc(o.company)}</strong><p class="pipe-pain">${esc(symptomName(o.priority))}</p><div class="chips">${o.solutions.slice(0,2).map(x=>`<span class="chip alt">${esc(x.split(' ').slice(0,2).join(' '))}</span>`).join('')}</div><div class="pipe-bottom"><span>${esc(repName(o.rep).split(' ')[0])}</span><span>${o.nextDate?dateFmt(o.nextDate):'Sem retorno'}</span></div></article>`).join(''):`<div class="pipe-empty">Nenhuma oportunidade</div>`}</section>`}).join('')}</div></div>`}
function renderAgenda(){const a=visible().filter(o=>o.nextDate&&!['Fechado','Perdido'].includes(o.stage)).sort((x,y)=>x.nextDate.localeCompare(y.nextDate));const groups=[{title:'Atrasados',test:o=>o.nextDate<dateISO(0)},{title:'Para hoje',test:o=>o.nextDate===dateISO(0)},{title:'Próximos contatos',test:o=>o.nextDate>dateISO(0)}];return heading('CONTINUIDADE COMERCIAL','Agenda e retornos','Uma oportunidade sem próximo movimento pode ficar esquecida. Cada compromisso permanece ligado ao diagnóstico.',actionBtn('Cadastrar oportunidade','new',true))+`<div class="surface pad">${groups.map(g=>{const list=a.filter(g.test);return `<section class="agenda-group"><div class="section-top"><h3>${g.title}</h3><span class="mini-status">${list.length} oportunidade(s)</span></div>${list.length?list.map(o=>{const d=dateShort(o.nextDate);return `<div class="agenda-row" data-open-id="${o.id}"><div class="agenda-date"><b>${d.day}</b><small>${d.month}</small></div><div class="agenda-body"><strong>${esc(o.company)}</strong><small>${esc(symptomName(o.priority))} · ${esc(repName(o.rep))} · ${esc(o.stage)}</small></div><span class="agenda-action">Abrir →</span></div>`}).join(''):`<div class="intro-note">Nenhum retorno ${g.title.toLowerCase()}.</div>`}</section>`}).join('')}</div>`}
function renderNetwork(){const arr=visible();return heading('REDE DE PROSPECÇÃO','Representantes','Toda oportunidade é atribuída à pessoa que originou o relacionamento. Acompanhamento não significa comissão já definida.')+`<div class="network-grid">${REPS.filter(r=>state.role==='manager'||r.id===state.role).map(r=>{const all=arr.filter(o=>o.rep===r.id),finished=all.filter(o=>o.stage==='Fechado');return `<article class="surface network-card"><div class="avatar" style="width:48px;height:48px;font-size:17px">${r.initials}</div><h3>${esc(r.name)}</h3><p>${esc(r.region)}</p><div class="network-score"><div><b>${all.length}</b><span>Oportunidades indicadas</span></div><div><b>${finished.length}</b><span>Fechadas (exemplo)</span></div></div></article>`}).join('')}</div><div class="intro-note network-warning"><strong>Atribuição comercial não é comissão.</strong> O protótipo registra quem trouxe a oportunidade, mas não calcula valores ou direitos de comissão. As regras de duplicidade, reabertura, participação na venda e pagamento precisam ser aprovadas antes da integração real.</div>`}
function openDrawer(id,tab='overview'){const o=get(id);if(!o||!visible().includes(o))return;state.activeOpp=id;state.tab=tab;Q('detailDrawer').classList.add('open');Q('detailDrawer').setAttribute('aria-hidden','false');Q('drawerOverlay').hidden=false;renderDrawer();document.body.style.overflow='hidden'}
function closeDrawer(){state.activeOpp=null;Q('detailDrawer').classList.remove('open');Q('detailDrawer').setAttribute('aria-hidden','true');Q('drawerOverlay').hidden=true;document.body.style.overflow=''}
function renderDrawer(){const o=get(state.activeOpp);if(!o)return;Q('drawerTitle').textContent=o.company;Q('drawerSubtitle').textContent=`${o.id} · ${o.sector} · origem: ${o.source||'Não informada'}`;for(const b of Q('drawerTabs').querySelectorAll('button'))b.classList.toggle('selected',b.dataset.tab===state.tab);Q('drawerBody').innerHTML=state.tab==='overview'?detailOverview(o):state.tab==='diagnosis'?detailDiagnosis(o):state.tab==='negotiation'?detailNegotiation(o):detailHistory(o);const diagForm=Q('diagnosisForm');if(diagForm)diagForm.addEventListener('submit',handleDiagnosis);const negForm=Q('negotiationForm');if(negForm)negForm.addEventListener('submit',handleNegotiation);Q('drawerNextAction').style.display=state.tab==='history'?'none':'';}
function metadata(label,value){return `<div class="metadata-box"><small>${label}</small><strong>${nice(value)}</strong></div>`}
function detailOverview(o){const s=SYMPTOMS.find(x=>x.id===o.priority)||SYMPTOMS[0];const related=visible().filter(x=>x.id!==o.id&&x.company.trim().toLocaleLowerCase('pt-BR')===o.company.trim().toLocaleLowerCase('pt-BR'));const relatedBlock=related.length?`<div class="drawer-section"><h3>Outras oportunidades desta empresa</h3><p>Uma empresa, vários projetos: o histórico comercial permanece separado por oportunidade.</p>${related.map(x=>`<button type="button" class="secondary-btn" style="margin:5px 7px 5px 0;white-space:normal;text-align:left" data-open-related="${esc(x.id)}">${esc(x.id)} · ${esc(symptomName(x.priority))} · ${esc(x.stage)} ↗</button>`).join('')}</div>`:'';const steps=['Verificar processo atual',...(o.solutions.slice(0,1).map(x=>`Avaliar ${x.toLowerCase()}`)),'Medir resultado esperado'];return `<div class="drawer-section"><div class="detail-heading"><span class="eyebrow">RESUMO DO PRÉ-DIAGNÓSTICO</span>${stagePill(o.stage)}</div><div class="detail-metadata">${metadata('Contato demonstrativo',o.contact)}${metadata('Representante de origem',repName(o.rep))}${metadata('Próximo contato',dateFmt(o.nextDate))}${metadata('Status da análise',o.diagnosisStatus)}</div><h3>Sintomas registrados</h3><div class="chips">${o.symptoms.map(k=>`<span class="chip">${esc(symptomName(k))}</span>`).join('')}</div></div><div class="drawer-section"><h3>O que o empresário relatou</h3><div class="highlight-block"><small>SINTOMA PRIORITÁRIO · ${esc(symptomName(o.priority).toUpperCase())}</small><p>${nice(o.description)}</p></div><span class="source-tag">Relato inicial não representa causa técnica comprovada.</span></div><div class="drawer-section"><h3>O que mais 30 dias podem significar</h3><div class="insight-note"><strong>Impacto registrado:</strong> ${nice(o.impact)}<br>É necessário validar volume, frequência, indicadores e premissas antes de concluir perda financeira.</div></div><div class="drawer-section"><h3>Possíveis soluções a investigar</h3><div class="chips">${o.solutions.length?o.solutions.map(x=>`<span class="chip alt">${esc(x)}</span>`).join(''):'A definir na avaliação Kadelta'}</div><p class="source-tag">Uma oportunidade pode combinar várias soluções; selecionar não significa aprovar desenvolvimento.</p></div><div class="drawer-section"><h3>Antes e depois (hipótese)</h3><div class="compare-flow"><div class="compare-col"><small>COMO PODE SER HOJE</small>${s.before.map(x=>`<div class="flow-step">${esc(x)}</div>`).join('')}</div><div class="compare-col after"><small>CAMINHO A VALIDAR</small>${steps.map(x=>`<div class="flow-step">${esc(x)}</div>`).join('')}</div></div></div>${relatedBlock}<button class="primary-btn" data-action="tab" data-tab="diagnosis">Aprofundar diagnóstico →</button>`}
function detailDiagnosis(o){const c=countFields(o);const f=[['Sintoma principal',Boolean(o.priority)],['Relato da situação',Boolean(o.description?.trim())],['Objetivo definido',Boolean(o.objective?.trim())],['Fluxo atual mapeado',Boolean(o.currentFlow?.trim())],['Sistemas identificados',Boolean(o.systems?.trim())],['Métrica de sucesso',Boolean(o.successMetric?.trim())]];const manager=state.role==='manager';return `<div class="diagnosis-progress"><div class="progress-label"><span>Preenchimento do diagnóstico</span><b>${c.score}/${c.total} · ${c.done}%</b></div><div class="progress-line"><span style="width:${c.done}%"></span></div><div class="diagnosis-checks">${f.map(([k,v])=>`<span class="diagnosis-check ${v?'yes':''}">${k}</span>`).join('')}</div></div>${manager?`<form id="diagnosisForm" class="form-stack"><input type="hidden" name="id" value="${esc(o.id)}"><div class="edit-panel"><h3>01 · Processo e problema</h3><label>Relato inicial (já registrado)<textarea name="description" rows="3">${esc(o.description)}</textarea></label><label>Objetivo que o cliente deseja atingir<textarea name="objective" rows="2" placeholder="O que mudaria se o problema fosse resolvido?">${esc(o.objective)}</textarea></label><label>Fluxo atual, do início ao fim<textarea name="currentFlow" rows="2" placeholder="Evento → pessoas → sistemas → consequência">${esc(o.currentFlow)}</textarea></label><label>Sistemas e dados envolvidos<input name="systems" value="${esc(o.systems)}" placeholder="ERP, WhatsApp, planilhas..." /></label></div><div class="edit-panel"><h3>02 · Como vamos medir</h3><label>Linha de base disponível<input name="baseline" value="${esc(o.baseline)}" placeholder="Ex.: 5 horas por semana, dados ainda não medidos..." /></label><label>Métrica verificável do resultado<input name="successMetric" value="${esc(o.successMetric)}" placeholder="Ex.: tempo até primeira resposta" /></label><label>Decisor / responsável pela validação<input name="approver" value="${esc(o.approver)}" placeholder="Cargo ou função que aprova o projeto" /></label><label>Restrições, dados, acessos e riscos<textarea name="constraints" rows="2" placeholder="Privacidade, APIs, dependências, exceções...">${esc(o.constraints)}</textarea></label><label>Estado do diagnóstico<select name="diagnosisStatus">${['A aprofundar','Aguardando dados','Em revisão','Validado para escopo','Não viável no momento'].map(x=>`<option ${o.diagnosisStatus===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="status-callout warn">Preenchimento completo não substitui a validação técnica e a concordância do responsável do cliente. Não prometer ROI, escopo ou prazo a partir desta ficha.</div><button class="primary-btn" type="submit">Salvar diagnóstico ↗</button></form>`:`<div class="intro-note"><strong>Visão de representante.</strong> Você acompanha o estado do diagnóstico, mas a revisão técnica é realizada pela equipe Kadelta.</div><div class="detail-metadata">${metadata('Objetivo',o.objective)}${metadata('Fluxo atual',o.currentFlow)}${metadata('Sistemas identificados',o.systems)}${metadata('Linha de base',o.baseline)}${metadata('Métrica de sucesso',o.successMetric)}${metadata('Dependências e riscos',o.constraints)}</div>`}`}
function detailNegotiation(o){const manager=state.role==='manager';return `<div class="drawer-section"><h3>Relacionamento e atribuição</h3><div class="detail-metadata">${metadata('Representante de origem',repName(o.rep))}${metadata('Canal',o.source)}${metadata('Etapa atual',o.stage)}${metadata('Próximo contato',dateFmt(o.nextDate))}</div><div class="insight-note">A empresa pode ter múltiplas oportunidades com produtos diferentes. A autoria da indicação permanece registrada em cada uma delas.</div></div>${manager?`<form id="negotiationForm" class="form-stack"><input name="id" type="hidden" value="${esc(o.id)}"><div class="edit-panel"><h3>Atualizar a negociação</h3><label>Etapa comercial<select name="stage">${STAGES.map(x=>`<option ${o.stage===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Próximo contato<input name="nextDate" type="date" value="${esc(o.nextDate||'')}"></label><label>Valor indicativo da oportunidade (R$) <small>opcional, fictício e não aprovado</small><input type="number" name="value" min="0" step="any" value="${esc(o.value)}" placeholder="Não informar se não houver proposta"></label></div><div class="status-callout warn">A demonstração não formaliza uma proposta, contrato ou comissão. O valor indicativo é apenas informativo e deve ser aprovado por processo comercial próprio.</div><button class="primary-btn" type="submit">Salvar evolução da negociação ↗</button></form>`:`<div class="intro-note"><strong>Acompanhamento comercial:</strong> o representante visualiza o estágio e a próxima ação. Informações financeiras e decisões internas ficam restritas à gestão.</div><button class="secondary-btn" data-action="add-activity" data-id="${o.id}">Registrar contato com cliente</button>`}`}
function detailHistory(o){const events=[...o.events].sort((a,b)=>b.at.localeCompare(a.at));return `<div class="drawer-section"><div class="section-top"><div><h3>Histórico de relacionamento</h3><p class="section-sub">Toda movimentação ou atualização comercial permanece vinculada a esta oportunidade.</p></div><button class="secondary-btn" data-action="add-activity" data-id="${o.id}">${ic('plus',16)} Atividade</button></div><div class="timeline">${events.map(e=>`<div class="timeline-item"><small>${asDate(e.at)?.toLocaleString('pt-BR',{dateStyle:'medium',timeStyle:'short'})||''} · ${esc(e.by||'Kadelta')}</small><strong>${esc(e.title)}</strong><p>${esc(e.detail||'')}</p></div>`).join('')}</div></div>`}
function bindNewModal(){Q('newSector').innerHTML='<option value="">Selecione</option>'+SECTORS.map(s=>`<option>${esc(s)}</option>`).join('');Q('newRep').innerHTML=REPS.map(r=>`<option value="${r.id}" ${state.role===r.id?'selected':''}>${esc(r.name)}</option>`).join('');Q('newRep').disabled=state.role!=='manager';Q('newPriority').innerHTML='<option value="">Selecione</option>'+SYMPTOMS.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');Q('newStage').innerHTML=STAGES.slice(0,3).map(s=>`<option>${esc(s)}</option>`).join('');Q('newSolutions').innerHTML=SOLUTIONS.map(s=>`<label class="check-pill"><input type="checkbox" value="${esc(s)}" name="solutions">${esc(s)}</label>`).join('')}
function newModal(){Q('newLeadForm').reset();bindNewModal();Q('newLeadDialog').showModal()}
function addLead(e){e.preventDefault();const d=new FormData(e.currentTarget);const company=String(d.get('company')||'').trim(),description=String(d.get('description')||'').trim(),contact=String(d.get('contact')||'').trim();if(!company||!contact||description.length<8)return toast('Preencha empresa, contato e situação.');const now=new Date().toISOString();const ref='KD-'+Math.floor(1000+Math.random()*8000);const opp={id:ref,company,contact,sector:String(d.get('sector')),rep:state.role==='manager'?String(d.get('rep')||REPS[0].id):state.role,stage:String(d.get('stage')),source:'Cadastro manual (demonstração)',symptoms:[String(d.get('priority'))],priority:String(d.get('priority')),description,solutions:d.getAll('solutions').map(String),frequency:'Ainda não informado',consequence:'Ainda não informado',impact:'Ainda sem dados para estimar.',objective:'',currentFlow:'',systems:'',baseline:'',successMetric:'',approver:'',constraints:'',diagnosisStatus:'A aprofundar',value:'',nextDate:String(d.get('nextDate')||''),createdAt:now,updatedAt:now,events:[{id:idNew(),at:now,kind:'lead',title:'Oportunidade registrada',detail:'Cadastro demonstrativo feito pelo painel.',by:state.role==='manager'?'Gestão Kadelta':repName(state.role)}]};data.opps.push(opp);persist();Q('newLeadDialog').close();setView('leads');openDrawer(opp.id);toast('Oportunidade fictícia cadastrada.')}
function importModal(){Q('importText').value='';Q('importFile').value='';Q('importDialog').showModal()}
function parseSummary(text){if(!text.includes('KADELTA | MAPA DE OPORTUNIDADE'))throw Error('Resumo não reconhecido. Copie o texto da última etapa da apresentação.');const lines=text.split(/\r?\n/);const line=(key)=>{const row=lines.find(x=>x.toLocaleLowerCase('pt-BR').startsWith(key.toLocaleLowerCase('pt-BR')+':'));return row?.slice(row.indexOf(':')+1).trim()||''};const sector=line('Setor');const sectorResolved=SECTORS.includes(sector)?sector:sector==='Energia solar'?'Engenharia e obras':'Outro setor';const names=line('Sintomas identificados').split(';').map(x=>x.trim()).filter(Boolean);const symptoms=SYMPTOMS.filter(x=>names.some(n=>n.toLocaleLowerCase('pt-BR')===x.name.toLocaleLowerCase('pt-BR'))).map(x=>x.id);const priorityStr=line('Prioridade');const priority=SYMPTOMS.find(x=>x.name===priorityStr)?.id||symptoms[0]||'manual';const solutions=line('Soluções a avaliar').split(';').map(x=>x.trim()).filter(x=>SOLUTIONS.includes(x));return {sector:sectorResolved,symptoms:symptoms.length?symptoms:[priority],priority,description:line('Situação relatada')||'A confirmar com o empresário.',frequency:line('Frequência'),consequence:line('Consequência'),impact:line('Mais 30 dias — cenário'),solutions,company:line('Empresa'),contact:line('Contato'),rep:line('Representante'),demo:/EXEMPLO FICTÍCIO/i.test(text)}}
function importLead(){try{const raw=Q('importText').value.trim();const r=parseSummary(raw);if(!r.demo&&!window.confirm('Este resumo não está marcado como fictício. Este painel é público e sem autenticação. NÃO importe dados pessoais reais. Só continue se todas as informações forem fictícias.'))return;const now=new Date().toISOString();const rep=state.role==='manager'?(REPS.find(x=>x.name.toLowerCase()===r.rep.toLowerCase())?.id||REPS[0].id):state.role;const opp={id:'KD-'+Math.floor(1000+Math.random()*8000),company:r.company&&r.company!=='Não informado'?r.company:'Empresa de demonstração',contact:r.contact&&r.contact!=='Não informado'?r.contact:'Contato de demonstração',sector:r.sector,rep,stage:'Novo',source:'Importação do pré-diagnóstico',symptoms:r.symptoms,priority:r.priority,description:r.description,solutions:r.solutions,frequency:r.frequency,consequence:r.consequence,impact:r.impact||'Sem dados numéricos',objective:'',currentFlow:'',systems:'',baseline:'',successMetric:'',approver:'',constraints:'',diagnosisStatus:'A aprofundar',value:'',nextDate:'',createdAt:now,updatedAt:now,events:[{id:idNew(),at:now,kind:'lead',title:'Pré-diagnóstico importado',detail:'Importação manual do resumo da apresentação adaptativa.',by:repName(rep)}]};data.opps.push(opp);persist();Q('importDialog').close();setView('leads');openDrawer(opp.id);toast('Pré-diagnóstico de demonstração importado.')}catch(err){toast(String(err.message||err))}}
function handleActivity(e){e.preventDefault();const d=new FormData(e.currentTarget),o=get(String(d.get('oppId')));if(!o)return;const val=String(d.get('description')||'').trim();if(val.length<4)return toast('Descreva a atividade.');const type=String(d.get('type')||'note'),labels={note:'Nota comercial',call:'Ligação registrada',meeting:'Reunião registrada',whatsapp:'Contato por WhatsApp',task:'Tarefa agendada'};const nextDate=String(d.get('nextDate')||'');if(nextDate)o.nextDate=nextDate;saveOpp(o,labels[type]||'Atividade registrada',val+(nextDate?' | Próximo retorno: '+dateFmt(nextDate):''));Q('activityDialog').close();e.currentTarget.reset();state.tab='history';renderDrawer()}
function activityModal(id){if(!get(id))return;Q('activityForm').reset();Q('activityOppId').value=id;Q('activityDialog').showModal()}
function handleDiagnosis(e){e.preventDefault();if(state.role!=='manager')return;const d=new FormData(e.currentTarget),o=get(String(d.get('id')));if(!o)return;for(const k of ['description','objective','currentFlow','systems','baseline','successMetric','approver','constraints','diagnosisStatus'])o[k]=String(d.get(k)||'').trim().slice(0,2500);saveOpp(o,'Diagnóstico atualizado','Fluxo, resultado pretendido ou dependências revisados pela equipe Kadelta.')}
function handleNegotiation(e){e.preventDefault();if(state.role!=='manager')return;const d=new FormData(e.currentTarget),o=get(String(d.get('id')));if(!o)return;const previous=o.stage;const st=String(d.get('stage'));if(!STAGES.includes(st))return;const v=String(d.get('value')||'');if(v&&(!Number.isFinite(Number(v))||Number(v)<0))return toast('Informe um valor válido ou deixe vazio.');o.stage=st;o.value=v;o.nextDate=String(d.get('nextDate')||'');saveOpp(o,previous!==st?'Etapa comercial alterada':'Negociação atualizada',previous!==st?`${previous} → ${st}`:'Dados de acompanhamento comercial atualizados.')}
function changeStage(id,stage){const o=get(id);if(!o||state.role!=='manager'||!STAGES.includes(stage)||o.stage===stage)return;const old=o.stage;o.stage=stage;saveOpp(o,'Etapa comercial alterada',`${old} → ${stage}`)}
function exportData(){const payload={demo:true,notice:'SOMENTE EXEMPLOS FICTÍCIOS; NÃO IMPORTAR DADOS REAIS',savedAt:new Date().toISOString(),...data};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='kadelta-gestao-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Dados da demonstração exportados como JSON.')}
function resetAll(){if(!window.confirm('Restaurar TODOS os registros fictícios iniciais e descartar alterações deste navegador?'))return;data=seed();persist();closeDrawer();setView('dashboard');toast('Exemplos restaurados.')}
function readInbox(){let s='';try{s=localStorage.getItem(INBOX_KEY)||''}catch(e){}if(!s)return;Q('importText').value=s;Q('importDialog').showModal();try{localStorage.removeItem(INBOX_KEY)}catch(e){}}
function init(){for(const n of document.querySelectorAll('[data-icon]'))n.innerHTML=ic(n.dataset.icon,17);Q('sideNav').addEventListener('click',e=>{const t=e.target.closest('[data-view]');if(t)setView(t.dataset.view)});Q('menuButton').addEventListener('click',()=>{Q('sidebar').classList.add('open');Q('mobileScrim').hidden=false});Q('mobileScrim').addEventListener('click',()=>{Q('sidebar').classList.remove('open');Q('mobileScrim').hidden=true});Q('roleSelect').addEventListener('change',e=>{state.role=e.target.value;state.search='';state.filterStage='all';closeDrawer();setView('dashboard');toast(state.role==='manager'?'Visão geral da gestão Kadelta.':'Exibindo somente oportunidades do representante.');});Q('newLeadTop').addEventListener('click',newModal);Q('dismissNotice').addEventListener('click',()=>{Q('noticeBar').remove()});Q('drawerClose').addEventListener('click',closeDrawer);Q('drawerOverlay').addEventListener('click',closeDrawer);Q('drawerTabs').addEventListener('click',e=>{const t=e.target.closest('[data-tab]');if(t){state.tab=t.dataset.tab;renderDrawer()}});Q('drawerNextAction').addEventListener('click',()=>activityModal(state.activeOpp));Q('drawerPrint').addEventListener('click',()=>window.print());document.querySelectorAll('[data-close-dialog]').forEach(btn=>btn.addEventListener('click',()=>Q(btn.dataset.closeDialog).close()));Q('newLeadForm').addEventListener('submit',addLead);Q('activityForm').addEventListener('submit',handleActivity);Q('doImport').addEventListener('click',importLead);Q('importFile').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>400000)return toast('Arquivo muito grande para esta demonstração.');Q('importText').value=await f.text()});
Q('view').addEventListener('click',e=>{const v=e.target.closest('[data-open-id]');if(v){openDrawer(v.dataset.openId);return}const a=e.target.closest('[data-action]');if(!a)return;switch(a.dataset.action){case 'switch':setView(a.dataset.target);break;case 'new':newModal();break;case 'import':importModal();break;case 'export':exportData();break;case 'reset':resetAll();break;}});
Q('view').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-open-id][role="button"]')){e.preventDefault();openDrawer(e.target.dataset.openId)}});
Q('view').addEventListener('input',e=>{if(e.target.id==='leadSearch'){state.search=e.target.value;const p=e.target.selectionStart;render();const el=Q('leadSearch');el?.focus();if(el?.setSelectionRange)el.setSelectionRange(p,p)}});
Q('view').addEventListener('change',e=>{if(e.target.id==='stageFilter'){state.filterStage=e.target.value;render()}if(e.target.id==='sectorFilter'){state.filterSector=e.target.value;render()}});
Q('view').addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag-id]');if(!card||state.role!=='manager')return;card.classList.add('dragging');e.dataTransfer.setData('text/plain',card.dataset.dragId);e.dataTransfer.effectAllowed='move'});
Q('view').addEventListener('dragend',e=>{e.target.closest('[data-drag-id]')?.classList.remove('dragging');document.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'))});
Q('view').addEventListener('dragover',e=>{const col=e.target.closest('[data-drop-stage]');if(col&&state.role==='manager'){e.preventDefault();e.dataTransfer.dropEffect='move';col.classList.add('drag-over')}});
Q('view').addEventListener('dragleave',e=>{const col=e.target.closest('[data-drop-stage]');if(col&&!col.contains(e.relatedTarget))col.classList.remove('drag-over')});
Q('view').addEventListener('drop',e=>{const col=e.target.closest('[data-drop-stage]');if(!col)return;e.preventDefault();const id=e.dataTransfer.getData('text/plain');changeStage(id,col.dataset.dropStage)});

Q('drawerBody').addEventListener('click',e=>{const related=e.target.closest('[data-open-related]');if(related){openDrawer(related.dataset.openRelated);return}const a=e.target.closest('[data-action]');if(!a)return;if(a.dataset.action==='tab'){state.tab=a.dataset.tab;renderDrawer()}if(a.dataset.action==='add-activity')activityModal(a.dataset.id)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.activeOpp&&!document.querySelector('dialog[open]'))closeDrawer()});
for(const id of ['newLeadDialog','importDialog','activityDialog'])Q(id).addEventListener('click',e=>{if(e.target===Q(id))Q(id).close()});
const url=new URLSearchParams(window.location.search);if(url.get('from')==='presentation')setTimeout(readInbox,250);render();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();